def reference(x, y):
    @functools.cache
    def length(i, j):
        if i == 0 or j == 0:
            return 0
        if x[i - 1] == y[j - 1]:
            return length(i - 1, j - 1) + 1
        return max(length(i - 1, j), length(i, j - 1))

    @functools.cache
    def pick(i, j):
        if i == 0 or j == 0:
            return ""
        here = length(i, j)
        if x[i - 1] == y[j - 1] and here == length(i - 1, j - 1) + 1:
            return pick(i - 1, j - 1) + x[i - 1]
        if here == length(i - 1, j - 1):
            return pick(i - 1, j - 1)
        if here == length(i - 1, j):
            return pick(i - 1, j)
        return pick(i, j - 1)

    return length(len(x), len(y)), pick(len(x), len(y))

