        raise ValueError(f"n must be greater than 0. Got n = {number}")

    @functools.cache
    def steps(n):
        if n == 1:
            return 0
        options = [steps(n - 1)]
        if n % 2 == 0:
            options.append(steps(n // 2))
        if n % 3 == 0:
            options.append(steps(n // 3))
        return 1 + min(options)

