def reference(first_string, second_string):
    a, b = first_string, second_string

    @lru_cache(maxsize=None)
    def dist(i, j):
        if i == 0:
            return j
        if j == 0:
            return i
        best = min(dist(i - 1, j) + 1, dist(i, j - 1) + 1, dist(i - 1, j - 1) + int(a[i - 1] != b[j - 1]))
        if i > 1 and j > 1 and a[i - 1] == b[j - 2] and a[i - 2] == b[j - 1]:
            best = min(best, dist(i - 2, j - 2) + 1)
        return best

    return dist(len(a), len(b))

